CREATE FUNCTION touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW."updatedAt" = CURRENT_TIMESTAMP; RETURN NEW; END $$;

-- PostgreSQL baseline of the existing MySQL application schema.
-- Run inside a transaction with a private application search_path.
CREATE TABLE "admin_activity_log" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "adminId" INTEGER NOT NULL,
  "action" varchar(255) NOT NULL,
  "details" text,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "ai_usage" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" INTEGER NOT NULL,
  "type" varchar(50) NOT NULL,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX "ai_usage_idx_user_type" ON "ai_usage" ("userId", "type");

CREATE TABLE "api_keys" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(100) NOT NULL,
  "provider" varchar(50) DEFAULT 'gemini',
  "model" varchar(100) DEFAULT 'gemini-2.5-flash',
  "customEndpoint" varchar(255),
  "apiKey" text NOT NULL,
  "isActive" SMALLINT DEFAULT '1',
  "isDisabled" SMALLINT DEFAULT '0',
  "totalRequests" INTEGER DEFAULT '0',
  "totalTokens" BIGINT DEFAULT '0',
  "totalErrors" INTEGER DEFAULT '0',
  "lastUsedAt" TIMESTAMPTZ,
  "lastErrorAt" TIMESTAMPTZ,
  "lastErrorMessage" text,
  "dailyRequests" INTEGER DEFAULT '0',
  "dailyTokens" BIGINT DEFAULT '0',
  "dailyResetAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  "monthlyRequests" INTEGER DEFAULT '0',
  "monthlyTokens" BIGINT DEFAULT '0',
  "monthlyResetAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  "cooldownUntil" TIMESTAMPTZ,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "api_usage_log" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "apiKeyId" INTEGER NOT NULL,
  "userId" INTEGER,
  "endpoint" varchar(100),
  "inputTokens" INTEGER DEFAULT '0',
  "outputTokens" INTEGER DEFAULT '0',
  "responseTimeMs" INTEGER DEFAULT '0',
  "statusCode" INTEGER DEFAULT '200',
  "errorMessage" text,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX "api_usage_log_idx_apikey_date" ON "api_usage_log" ("apiKeyId", "createdAt");
CREATE INDEX "api_usage_log_idx_user_date" ON "api_usage_log" ("userId", "createdAt");

CREATE TABLE "applications" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" INTEGER,
  "jobTitle" varchar(255),
  "company" varchar(255),
  "location" varchar(255),
  "salary" varchar(100),
  "status" varchar(50) DEFAULT 'applied',
  "matchScore" INTEGER,
  "appliedAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "auth_tokens" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" INTEGER NOT NULL,
  "type" varchar(50) NOT NULL,
  "tokenHash" char(64) NOT NULL,
  "expiresAt" TIMESTAMPTZ NOT NULL,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "auth_tokens_unique_auth_token" ON "auth_tokens" ("tokenHash");
CREATE INDEX "auth_tokens_idx_auth_tokens_user_type" ON "auth_tokens" ("userId", "type");

CREATE TABLE "chats" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" INTEGER,
  "title" varchar(255),
  "pinned" SMALLINT DEFAULT '0',
  "archived" SMALLINT DEFAULT '0',
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "company_email_attachments" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "emailId" INTEGER NOT NULL,
  "fileName" varchar(255) NOT NULL,
  "fileType" varchar(100),
  "fileSize" INTEGER,
  "fileData" TEXT,
  PRIMARY KEY ("id")
);
CREATE INDEX "company_email_attachments_idx_emailId" ON "company_email_attachments" ("emailId");

CREATE TABLE "company_emails" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "threadId" varchar(255) NOT NULL,
  "mailbox" varchar(100) NOT NULL,
  "subject" varchar(255) NOT NULL,
  "senderName" varchar(100),
  "senderEmail" varchar(255) NOT NULL,
  "recipientEmail" varchar(255) NOT NULL,
  "body" TEXT,
  "status" varchar(50) DEFAULT 'New',
  "assignedAdminId" INTEGER,
  "direction" varchar(20) DEFAULT 'incoming',
  "hasAttachments" SMALLINT DEFAULT '0',
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  "scheduledAt" TIMESTAMPTZ,
  PRIMARY KEY ("id")
);

CREATE TABLE "email_delivery_logs" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "recipient" varchar(255) NOT NULL,
  "templateName" varchar(100) NOT NULL,
  "templateVersion" varchar(20) NOT NULL,
  "status" varchar(50) NOT NULL,
  "providerResponse" text,
  "smtpCode" varchar(50),
  "sendDurationMs" INTEGER,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "email_queue" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "recipient" varchar(255) NOT NULL,
  "templateName" varchar(100) NOT NULL,
  "templateVersion" varchar(20) NOT NULL,
  "payload" TEXT NOT NULL,
  "status" varchar(50) DEFAULT 'pending',
  "attempts" INTEGER DEFAULT '0',
  "lastError" text,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX "email_queue_idx_status" ON "email_queue" ("status");
CREATE TRIGGER "email_queue_updated_at" BEFORE UPDATE ON "email_queue" FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

CREATE TABLE "files" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" INTEGER NOT NULL,
  "type" varchar(50) NOT NULL,
  "title" varchar(255) NOT NULL,
  "content" TEXT,
  "jobId" INTEGER,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX "files_idx_files_user" ON "files" ("userId");

CREATE TABLE "interviews" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" INTEGER NOT NULL,
  "role" varchar(255) NOT NULL,
  "difficulty" varchar(50) NOT NULL,
  "overall_score" decimal(5,2) DEFAULT '0.00',
  "questions_json" TEXT,
  "answers_json" TEXT,
  "feedback_json" TEXT,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX "interviews_idx_interviews_user" ON "interviews" ("user_id");

CREATE TABLE "job_providers" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(50) NOT NULL,
  "displayName" varchar(100) NOT NULL,
  "apiKey" text,
  "appId" text,
  "priority" INTEGER DEFAULT '1',
  "status" varchar(20) DEFAULT 'disabled',
  "latencyMs" INTEGER DEFAULT '0',
  "errorRate" decimal(5,2) DEFAULT '0.00',
  "dailyRequests" INTEGER DEFAULT '0',
  "monthlyRequests" INTEGER DEFAULT '0',
  "healthScore" INTEGER DEFAULT '100',
  "lastTestedAt" TIMESTAMPTZ,
  "updatedAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "job_providers_name" ON "job_providers" ("name");
CREATE TRIGGER "job_providers_updated_at" BEFORE UPDATE ON "job_providers" FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

CREATE TABLE "job_search_cache" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "cacheKey" char(64) NOT NULL,
  "query" varchar(255),
  "location" varchar(255),
  "results" TEXT,
  "resultCount" INTEGER DEFAULT '0',
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "job_search_cache_cacheKey" ON "job_search_cache" ("cacheKey");

CREATE TABLE "jobs" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "title" varchar(255) NOT NULL,
  "company" varchar(255) NOT NULL,
  "location" varchar(255),
  "description" text,
  "url" varchar(1000),
  "platform" varchar(100),
  "match_score" INTEGER DEFAULT '0',
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "login_audit_logs" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "email" varchar(255) NOT NULL,
  "userId" INTEGER,
  "browser" varchar(100),
  "os" varchar(100),
  "device" varchar(50),
  "ipAddress" varchar(100),
  "country" varchar(100),
  "result" varchar(20) NOT NULL,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "messages" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "chatId" INTEGER,
  "role" varchar(20),
  "content" text,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "payment_orders" (
  "orderId" varchar(100) NOT NULL,
  "userId" INTEGER NOT NULL,
  "planName" varchar(50) NOT NULL,
  "amount" BIGINT NOT NULL,
  "currency" varchar(3) NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'pending',
  "paymentId" varchar(100),
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  "billing" varchar(10) NOT NULL DEFAULT 'monthly',
  PRIMARY KEY ("orderId")
);
CREATE UNIQUE INDEX "payment_orders_paymentId" ON "payment_orders" ("paymentId");

CREATE TABLE "payments" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" INTEGER NOT NULL,
  "orderId" varchar(255) NOT NULL,
  "paymentId" varchar(255) NOT NULL,
  "planName" varchar(50) NOT NULL,
  "amount" decimal(10,2) NOT NULL,
  "currency" varchar(10) DEFAULT 'USD',
  "status" varchar(50) DEFAULT 'success',
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "plans" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(50) NOT NULL,
  "price_inr" decimal(10,2) DEFAULT '0.00',
  "price_usd" decimal(10,2) DEFAULT '0.00',
  "features" text,
  "limits" text,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "plans_name" ON "plans" ("name");

CREATE TABLE "security_logs" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" INTEGER,
  "email" varchar(255) NOT NULL,
  "action" varchar(255) NOT NULL,
  "ipAddress" varchar(100),
  "userAgent" varchar(500),
  "details" text,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "shared_chats" (
  "id" varchar(50) NOT NULL,
  "title" varchar(255),
  "messages" TEXT,
  "options" TEXT,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "support_tickets" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(100),
  "email" varchar(255),
  "subject" varchar(200),
  "message" text,
  "category" varchar(50),
  "status" varchar(50) DEFAULT 'new',
  "repliedAt" TIMESTAMPTZ,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  "assignedAdminId" INTEGER,
  "internalNotes" text,
  "attachments" TEXT,
  "replies" TEXT,
  PRIMARY KEY ("id")
);

CREATE TABLE "update_subscribers" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "email" varchar(254) NOT NULL,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "update_subscribers_email" ON "update_subscribers" ("email");

CREATE TABLE "users" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "firstName" varchar(100),
  "lastName" varchar(100),
  "email" varchar(255),
  "phone" varchar(20),
  "passwordHash" varchar(255),
  "plan" varchar(50) DEFAULT 'free',
  "role" varchar(50) DEFAULT 'user',
  "isVerified" SMALLINT DEFAULT '0',
  "linkedinUrl" varchar(500),
  "indeedUrl" varchar(500),
  "naukriUrl" varchar(500),
  "githubUrl" varchar(500),
  "lastLoginAt" TIMESTAMPTZ,
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  "adminNotes" text,
  "isSuspended" SMALLINT DEFAULT '0',
  "adminRoleName" varchar(100),
  "adminPermissions" text,
  "otpCode" varchar(255),
  "otpExpiresAt" TIMESTAMPTZ,
  "device" varchar(50) DEFAULT 'Desktop',
  "createdById" INTEGER,
  "tokenVersion" INTEGER DEFAULT '1',
  "browser" varchar(100),
  "ipAddress" varchar(100),
  "lastActiveAt" TIMESTAMPTZ,
  "lastAction" varchar(255),
  "sessionStatus" varchar(50) DEFAULT 'offline',
  "totalLogins" INTEGER DEFAULT '0',
  "os" varchar(100),
  "country" varchar(100),
  "city" varchar(100),
  "verificationStatus" varchar(50) DEFAULT 'Pending Verification',
  "verifiedAt" TIMESTAMPTZ,
  "planExpiresAt" TIMESTAMPTZ,
  PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "users_email" ON "users" ("email");
CREATE TRIGGER "users_updated_at" BEFORE UPDATE ON "users" FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

CREATE TABLE "verification_logs" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" INTEGER,
  "email" varchar(255) NOT NULL,
  "otpCode" varchar(10) NOT NULL,
  "status" varchar(50) NOT NULL,
  "ipAddress" varchar(100),
  "userAgent" varchar(500),
  "createdAt" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

-- PostgreSQL unique checks must preserve case-insensitive account identity.
CREATE UNIQUE INDEX users_email_normalized ON users (LOWER(email));
CREATE UNIQUE INDEX update_subscribers_email_normalized ON update_subscribers (LOWER(email));
CREATE TABLE schema_migrations (version TEXT PRIMARY KEY, "appliedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO schema_migrations(version) VALUES ('001_initial');
